81	 *  today) or a date yyyy-mm-dd, and permission entries (when given) only for open, settle, void, reassign, close or
82	 *  reopen, each blank (the standing rule) or a comma separated list of clerk and steward, and grace days (when given) blank (off) or a whole number of days, and a note threshold (when given) blank (none) or an amount 0.00 or more with up to two decimals, and an entry date (when given) blank (off) or a date yyyy-mm-dd, and grades' grace (when given) only for grades A, B or C, each blank (none) or a whole number of days, and a pot (when given) blank (none) or an amount 0.00 or more with up to two decimals, and an escalation gap (when given) blank (off) or a whole number of days, and proof kinds (when given) blank (none) or a comma separated list of receipt and photo. A rounding mode (when given) is blank (none) or half-up or half-even. A fiscal year start month (when given) is a month 1 to 12. The parent sheet (when given) is
83	 *  checked against the store by ValidateParent. */
84	public class ValidateSettings {
85	    /** The grades that may have terms of their own. */
86	    static final List<String> GRADES = List.of("A", "B", "C");
87	
88	    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
89	    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";
90	
91	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
92	        if (request == null || request.user() == null || request.user().isBlank()) {
93	            throw new InvalidSettingException("Sign in before changing settings.");
94	        }
95	        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
96	        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
97	            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
98	        }
99	        String floor = request.floor() == null ? null : request.floor().trim();
100	        if (floor != null && !floor.matches(AMOUNT)) {
101	            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
102	        }
103	        String terms = request.terms() == null ? null : request.terms().trim();
104	        if (terms != null && !terms.matches("\\d{1,4}")) {
105	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
106	        }
107	        String latePct = request.latePct() == null ? null : request.latePct().trim();
108	        if (latePct != null && !latePct.matches(PERCENT)) {
109	            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
110	        }
111	        String policy = request.policyDate() == null ? null : request.policyDate().trim();
112	        LocalDate policyDate = null;
113	        if (policy != null && !policy.isEmpty()) {
114	            try {
115	                policyDate = LocalDate.parse(policy);
116	            } catch (DateTimeParseException e) {
117	                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
118	            }
119	        }
120	        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
121	        LocalDate numberingFrom = null;
122	        if (numbering != null && !numbering.isEmpty()) {
123	            try {
124	                numberingFrom = LocalDate.parse(numbering);
125	            } catch (DateTimeParseException e) {
126	                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
127	            }
128	        }
129	        String cap = request.cap() == null ? null : request.cap().trim();
130	        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
131	            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
132	        }
133	        String threshold = request.proofThreshold() == null ? null : request.proofThreshold().trim();
134	        if (threshold != null && !threshold.isEmpty() && !threshold.matches(AMOUNT)) {
135	            throw new InvalidSettingException("The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
136	        }
137	        String noteThreshold = request.noteThreshold() == null ? null : request.noteThreshold().trim();
138	        if (noteThreshold != null && !noteThreshold.isEmpty() && !noteThreshold.matches(AMOUNT)) {
139	            throw new InvalidSettingException("The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
140	        }
141	        String reviewThreshold = request.reviewThreshold() == null ? null : request.reviewThreshold().trim();
142	        if (reviewThreshold != null && !reviewThreshold.isEmpty() && !reviewThreshold.matches(AMOUNT)) {
143	            throw new InvalidSettingException("The review threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
144	        }
145	        String grace = request.graceDays() == null ? null : request.graceDays().trim();
146	        if (grace != null && !grace.isEmpty() && !grace.matches("\\d{1,4}")) {
147	            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank for off.");
148	        }
149	        String escalate = request.escalateAfter() == null ? null : request.escalateAfter().trim();
150	        if (escalate != null && !escalate.isEmpty() && !escalate.matches("\\d{1,4}")) {
151	            throw new InvalidSettingException("The escalation gap must be a whole number of days, 0 or more, or blank for off.");
152	        }
153	        String reviewSla = request.reviewSla() == null ? null : request.reviewSla().trim();
154	        if (reviewSla != null && !reviewSla.isEmpty() && !reviewSla.matches("\\d{1,4}")) {
155	            throw new InvalidSettingException("The review SLA must be a whole number of days, 0 or more, or blank for none.");
156	        }
157	        String proofKinds = request.proofKinds() == null ? null : proofKinds(request.proofKinds());
158	        String entered = request.entryDate() == null ? null : request.entryDate().trim();
159	        LocalDate entryDate = null;
160	        if (entered != null && !entered.isEmpty()) {
161	            try {
162	                entryDate = LocalDate.parse(entered);
163	            } catch (DateTimeParseException e) {
164	                throw new InvalidSettingException("The entry date must be a date, yyyy-mm-dd, or blank for off.");
165	            }
166	        }
167	        String pot = request.pot() == null ? null : request.pot().trim();
168	        if (pot != null && !pot.isEmpty() && !pot.matches(AMOUNT)) {
169	            throw new InvalidSettingException("The pot must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
170	        }
171	        String alert = request.alertThreshold() == null ? null : request.alertThreshold().trim();
172	        if (alert != null && !alert.isEmpty() && !alert.matches(AMOUNT)) {
173	            throw new InvalidSettingException("The alert threshold must be an amount, 0.00 or more, with up to two decimals, or blank for off.");
174	        }
175	        String rounding = request.rounding() == null ? null : request.rounding().trim();
176	        if (rounding != null && !rounding.isEmpty() && !rounding.equals(SettingHistory.HALF_UP)
177	                && !rounding.equals(SettingHistory.HALF_EVEN)) {
178	            throw new InvalidSettingException("The rounding mode must be half-up or half-even, or blank for none.");
179	        }
180	        String parent = request.parent() == null ? null : request.parent().trim();
181	        String fiscal = request.fiscalStartMonth() == null ? null : request.fiscalStartMonth().trim();
182	        if (fiscal != null && !fiscal.matches("[1-9]|1[0-2]")) {
183	            throw new InvalidSettingException("The fiscal year start month must be a month, 1 to 12.");
184	        }
185	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
186	        if (request.gradeTerms() != null) {
187	            for (String grade : request.gradeTerms().keySet()) {
188	                if (!GRADES.contains(grade)) {
189	                    throw new InvalidSettingException("Terms may be set only for grade A, B or C.");
190	                }
191	            }
192	            for (String grade : GRADES) {
193	                if (!request.gradeTerms().containsKey(grade)) {
194	                    continue;
195	                }
196	                String days = request.gradeTerms().get(grade) == null ? "" : request.gradeTerms().get(grade).trim();
197	                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
198	                    throw new InvalidSettingException("The terms of grade " + grade
199	                            + " must be a whole number of days, 0 or more, or blank for the sheet's terms.");
200	                }
201	                gradeTerms.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
202	            }
203	        }
204	        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
205	        if (request.gradeGrace() != null) {
206	            for (String grade : request.gradeGrace().keySet()) {
207	                if (!GRADES.contains(grade)) {
208	                    throw new InvalidSettingException("Grace may be set only for grade A, B or C.");
209	                }
210	            }
211	            for (String grade : GRADES) {
212	                if (!request.gradeGrace().containsKey(grade)) {
213	                    continue;
214	                }
215	                String days = request.gradeGrace().get(grade) == null ? "" : request.gradeGrace().get(grade).trim();
216	                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
217	                    throw new InvalidSettingException("The grace of grade " + grade
218	                            + " must be a whole number of days, 0 or more, or blank for none.");
219	                }
220	                gradeGrace.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
221	            }
222	        }
223	        Map<String, BigDecimal> gradeProofThreshold = new LinkedHashMap<>();
224	        if (request.gradeProofThreshold() != null) {
225	            for (String grade : request.gradeProofThreshold().keySet()) {
226	                if (!GRADES.contains(grade)) {
227	                    throw new InvalidSettingException("A proof threshold may be set only for grade A, B or C.");
228	                }
229	            }
230	            for (String grade : GRADES) {
231	                if (!request.gradeProofThreshold().containsKey(grade)) {
232	                    continue;
233	                }
234	                String amount = request.gradeProofThreshold().get(grade) == null ? ""
235	                        : request.gradeProofThreshold().get(grade).trim();
236	                if (!amount.isEmpty() && !amount.matches(AMOUNT)) {
237	                    throw new InvalidSettingException("The proof threshold of grade " + grade
238	                            + " must be an amount, 0.00 or more, with up to two decimals, or blank for the sheet's.");
239	                }
240	                gradeProofThreshold.put(grade, amount.isEmpty() ? null : new BigDecimal(amount).setScale(2));
241	            }
242	        }
243	        Map<String, String> perms = new LinkedHashMap<>();
244	        if (request.perms() != null) {
245	            for (String action : request.perms().keySet()) {
246	                if (!Permissions.ACTIONS.contains(action)) {
247	                    throw new InvalidSettingException("Permissions may be set only for open, settle, void, reassign, close or reopen.");
248	                }
249	            }
250	            for (String action : Permissions.ACTIONS) {
251	                if (!request.perms().containsKey(action)) {
252	                    continue;
253	                }
254	                String entry = request.perms().get(action) == null ? "" : request.perms().get(action).trim();
255	                List<String> roles = new ArrayList<>();
256	                if (!entry.isEmpty()) {
257	                    for (String role : entry.split(",", -1)) {
258	                        String r = role.trim();
259	                        if (!r.equals(Role.CLERK) && !r.equals(Role.STEWARD)) {
260	                            throw new InvalidSettingException("The roles allowed to " + action
261	                                    + " must be a comma separated list of clerk and steward, or blank for the standing rule.");
262	                        }
263	                        if (!roles.contains(r)) {
264	                            roles.add(r);
265	                        }
266	                    }
267	                }
268	                perms.put(action, String.join(",", roles));
269	            }
270	        }
271	        Map<String, LocalDate> from = new LinkedHashMap<>();
272	        if (request.from() != null) {
273	            for (var e : request.from().entrySet()) {
274	                if (!SettingHistory.KEYS.contains(e.getKey())) {
275	                    throw new InvalidSettingException("Only a setting that carries a figure takes a from-date.");
276	                }
277	                String date = e.getValue() == null ? "" : e.getValue().trim();
278	                if (date.isEmpty()) {
279	                    continue;
280	                }
281	                try {
282	                    from.put(e.getKey(), LocalDate.parse(date));
283	                } catch (DateTimeParseException ex) {
284	                    throw new InvalidSettingException("The from-date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
285	                }
286	            }
287	        }
288	        body.set(new SettingsInput(request.user().trim(), limit != null,
289	                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
290	                floor == null ? null : new BigDecimal(floor).setScale(2),
291	                terms == null ? null : Integer.valueOf(terms),
292	                latePct == null ? null : new BigDecimal(latePct).setScale(2),
293	                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
294	                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from,
295	                threshold != null, threshold == null || threshold.isEmpty() ? null : new BigDecimal(threshold).setScale(2),
296	                perms, grace != null, grace == null || grace.isEmpty() ? null : Integer.valueOf(grace),
297	                noteThreshold != null,
298	                noteThreshold == null || noteThreshold.isEmpty() ? null : new BigDecimal(noteThreshold).setScale(2),
299	                entered != null, entryDate, gradeGrace, gradeProofThreshold,
300	                pot != null, pot == null || pot.isEmpty() ? null : new BigDecimal(pot).setScale(2),
301	                parent != null, parent == null || parent.isEmpty() ? null : parent,
302	                fiscal == null ? null : Integer.valueOf(fiscal),
303	                alert != null, alert == null || alert.isEmpty() ? null : new BigDecimal(alert).setScale(2),
304	                rounding != null, rounding == null || rounding.isEmpty() ? null : rounding,
305	                reviewThreshold != null,
306	                reviewThreshold == null || reviewThreshold.isEmpty() ? null : new BigDecimal(reviewThreshold).setScale(2),
307	                escalate != null, escalate == null || escalate.isEmpty() ? null : Integer.valueOf(escalate),
308	                reviewSla != null, reviewSla == null || reviewSla.isEmpty() ? null : Integer.valueOf(reviewSla),
309	                proofKinds != null, proofKinds == null || proofKinds.isEmpty() ? null : proofKinds));
310	    }
311	
312	    /** The proof kinds as stored: each listed kind trimmed, in the order given, without repeats, joined by commas ('':
313	     *  none); refused when one is not a proof kind (receipt or photo). */
314	    private static String proofKinds(String list) throws InvalidSettingException {
315	        var kinds = new java.util.LinkedHashSet<String>();
316	        for (String kind : list.split(",", -1)) {
317	            String k = kind.trim();
318	            if (k.isEmpty() && list.isBlank()) {
319	                continue;
320	            }
321	            if (!net.officefloor.hq.app.claim.Claim.PROOF_KINDS.contains(k)) {
322	                throw new InvalidSettingException("The proof kinds must be a comma separated list of "
323	                        + String.join(" and ", net.officefloor.hq.app.claim.Claim.PROOF_KINDS) + ", or blank for none.");
324	            }
325	            kinds.add(k);
326	        }
327	        return String.join(",", kinds);
328	    }
329	}
