338	/** Save the settings the input sets: each dated one recorded from its from-date (not given: the sheet's today),
339	 *  keeping the values already recorded (one from that same date is replaced); the policy date and the period
340	 *  numbering from and the grace days and the pot and the parent sheet and the fiscal year start month and the alert threshold and the escalation gap and the permission matrix as
341	 *  they are. */
342	public class SaveSettings {
343	    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
344	            Out<Settings> settings) {
345	        String id = sheetId.trim();
346	        LocalDate today = repository.today(id);
347	        if (input.setsClerkLimit()) {
348	            repository.setDated(id, "clerk-limit", text(input.clerkLimit()), from(input, "clerk-limit", today));
349	        }
350	        if (input.floor() != null) {
351	            repository.setDated(id, "floor", text(input.floor()), from(input, "floor", today));
352	        }
353	        if (input.terms() != null) {
354	            repository.setDated(id, "terms", String.valueOf(input.terms()), from(input, "terms", today));
355	        }
356	        input.gradeTerms().forEach((grade, days) -> repository.setDated(id, "terms-" + grade,
357	                days != null ? String.valueOf(days) : null, from(input, "terms-" + grade, today)));
358	        input.gradeGrace().forEach((grade, days) -> repository.setDated(id, "grace-" + grade,
359	                days != null ? String.valueOf(days) : null, from(input, "grace-" + grade, today)));
360	        input.gradeProofThreshold().forEach((grade, amount) -> repository.setDated(id, "proof-threshold-" + grade,
361	                text(amount), from(input, "proof-threshold-" + grade, today)));
362	        if (input.latePct() != null) {
363	            repository.setDated(id, "late-pct", text(input.latePct()), from(input, "late-pct", today));
364	        }
365	        if (input.setsPolicyDate()) {
366	            repository.setPolicyDate(id, input.policyDate());
367	        }
368	        if (input.setsPeriodNumberingFrom()) {
369	            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
370	        }
371	        if (input.setsCap()) {
372	            repository.setDated(id, "cap", text(input.cap()), from(input, "cap", today));
373	        }
374	        if (input.setsProofThreshold()) {
375	            repository.setDated(id, "proof-threshold", text(input.proofThreshold()), from(input, "proof-threshold", today));
376	        }
377	        if (input.setsNoteThreshold()) {
378	            repository.setDated(id, "note-threshold", text(input.noteThreshold()), from(input, "note-threshold", today));
379	        }
380	        if (input.setsGraceDays()) {
381	            repository.setGraceDays(id, input.graceDays());
382	        }
383	        if (input.setsEntryDate()) {
384	            repository.setEntryDate(id, input.entryDate());
385	        }
386	        if (input.setsPot()) {
387	            repository.setPot(id, input.pot());
388	        }
389	        if (input.setsParent()) {
390	            repository.setParent(id, input.parent());
391	        }
392	        if (input.fiscalStartMonth() != null) {
393	            repository.setFiscalStartMonth(id, input.fiscalStartMonth());
394	        }
395	        if (input.setsAlertThreshold()) {
396	            repository.setAlertThreshold(id, input.alertThreshold());
397	        }
398	        if (input.setsRounding()) {
399	            repository.setDated(id, SettingHistory.ROUNDING, input.rounding(), from(input, SettingHistory.ROUNDING, today));
400	        }
401	        if (input.setsReviewThreshold()) {
402	            repository.setDated(id, "review-threshold", text(input.reviewThreshold()), from(input, "review-threshold", today));
403	        }
404	        if (input.setsEscalateAfter()) {
405	            repository.setEscalateAfter(id, input.escalateAfter());
406	        }
407	        if (input.setsReviewSla()) {
408	            repository.setReviewSla(id, input.reviewSla());
409	        }
410	        if (input.setsProofKinds()) {
411	            repository.setProofKinds(id, input.proofKinds());
412	        }
413	        input.perms().forEach((action, roles) -> repository.setPermission(id, action, roles));
414	        settings.set(repository.of(id));
415	    }
416	
417	    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
418	        LocalDate from = input.from().get(key);
419	        return from != null ? from : today != null ? today : LocalDate.of(1, 1, 1);
420	    }
421	
422	    private static String text(BigDecimal value) {
423	        return value != null ? value.toPlainString() : null;
424	    }
425	}
